export const addTask = (task) => ({
  type: 'ADD_TASK',
  payload: task
});

export const markComplete = (id) => ({
  type: 'MARK_COMPLETE',
  payload: id
});

export const deleteTask = (id) => ({
  type: 'DELETE_TASK',
  payload: id
});
